"use client";

import Image from "next/image";
import { useState } from "react";
import { cn } from "@/lib/utils";

/**
 * Renders a sample portrait from /public/samples with a graceful placeholder if the
 * file is missing (samples are generated by a separate pipeline).
 */
export function SampleImage({
  src,
  alt,
  swatch = "#c8553d",
  label,
  className,
  sizes = "(max-width: 768px) 50vw, 25vw",
  priority,
}: {
  src: string;
  alt: string;
  swatch?: string;
  label?: string;
  className?: string;
  sizes?: string;
  priority?: boolean;
}) {
  const [failed, setFailed] = useState(false);
  return (
    <div className={cn("relative aspect-[4/5] overflow-hidden bg-paper-2", className)}>
      {failed ? (
        <div
          className="absolute inset-0 flex items-end p-4"
          style={{ background: `radial-gradient(120% 90% at 50% 30%, ${swatch}55, ${swatch} 70%)` }}
          role="img"
          aria-label={alt}
        >
          {label && <span className="font-display text-lg text-white/90">{label}</span>}
        </div>
      ) : (
        <Image
          src={src}
          alt={alt}
          fill
          sizes={sizes}
          priority={priority}
          className="object-cover"
          onError={() => setFailed(true)}
        />
      )}
    </div>
  );
}
